var n=`0595-tsuivan`;var i=`world-0595`;var o=`MN`;var a=`east-asia`;var s=4;var r=63;var l={en:`Tsuivan`,ua:`Цуйван`};var u={en:`A traditional dish from Mongolia, centered on all-purpose flour, chicken egg, beef chuck, yellow onion. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Монголія. Основні складники: пшеничне борошно універсальне, куряче яйце, яловича лопатка, жовта цибуля. Домашній варіант із кількостями продуктів за етапами приготування.`};var g=[{en:`Mix the dough ingredients, knead until smooth and elastic, then cover and rest for about 15 minutes.`,ua:`Змішайте складники тіста, вимісіть до гладкості й еластичності, накрийте та залиште приблизно на 15 хвилин.`,t:[`mixing`,`kneading`,`resting-dough`],m:15,i:[[`all-purpose-flour`,390,`g`],[`chicken-egg`,1,`pcs`],[`water`,155,`ml`],[`table-salt`,6,`g`]]},{en:`Roll or press the prepared dough evenly into the desired thickness and shape.`,ua:`Розкачайте або розпластайте підготовлене тісто рівномірним шаром потрібної товщини та форми.`,t:[`pressing`,`rolling-out-dough`],m:16,i:[]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 15 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 15 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:15,i:[[`beef-chuck`,480,`g`],[`yellow-onion`,190,`g`],[`carrot`,220,`g`],[`white-cabbage`,290,`g`],[`sunflower-oil`,55,`ml`]]},{en:`Lay the freshly cut noodles over the cooked meat and vegetables, pour in a little water, cover and steam-simmer until the noodles are tender; toss before serving.`,ua:`Розкладіть свіжу локшину поверх готового м’яса й овочів, додайте трохи води, накрийте й томіть на парі до м’якості локшини; перемішайте перед подаванням.`,t:[`stewing`],m:17,i:[[`water`,250,`ml`],[`light-soy-sauce`,50,`ml`]]}];var d={slug:n,id:i,country:`MN`,region:a,servings:4,minutes:63,title:l,text:u,steps:g};export{o as country,d as default,i as id,r as minutes,a as region,s as servings,n as slug,g as steps,u as text,l as title};